let l1;
let edge, frms = 600, rez;
let angle=PI/2;
let evenX, evenY;

function setup() {
  createCanvas(540, 540);
  edge = width/10;
  rez = 5;
  drawPattern();
}

function draw() {
  background(255);
  translate(edge, edge);
  imageMode(CORNER);
  image(l1, 0, 0);
  pushMatrix();
  imageMode(CENTER);
  translate(l1.width/2, l1.height/2);
  let r = map(sin(angle), -1, 1, 0, radians(90));
  rotate(r);
  image(l1, 0, 0);
  popMatrix();
  angle += TWO_PI/frms;
  //if (frameCount<=frms) saveFrame("image-###.gif");
}

function drawPattern() {
  l1 = createGraphics(width-edge*2, height-edge*2);
  l1.beginDraw();
  evenX = true;
  evenY = false;
  for (let x=0; x<=l1.width; x+=rez) {
    for (let y=0; y<=l1.height; y+=rez) {
      l1.noStroke();
      if (evenY) {
        l1.fill(0);
      } else {
        l1.noFill();
      }
      l1.rect(x, y, rez, rez);
      evenY = ! evenY;
    }
    evenX =! evenX;
  }
  l1.endDraw();
}

function mouseReleased() {
  drawPattern();
}
